def fetch_record(collection, id, expand=None, fields=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, collection_id=None, record_id=None, query=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "GET",
                "path": "/api/records/fetch",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id,
                "record_id": record_id,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"collection": collection, "id": id, "expand": expand, "fields": fields}

    if not isinstance(collection, str) or not collection.strip():
        _log(400, "collection must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "collection must be a non-empty string", field="collection")
    if not isinstance(id, str) or not id.strip():
        _log(400, "id must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    if expand is not None and not isinstance(expand, str):
        _log(400, "expand must be a string", query=q)
        return _err("VALIDATION_ERROR", "expand must be a string", field="expand")
    if fields is not None and not isinstance(fields, str):
        _log(400, "fields must be a string", query=q)
        return _err("VALIDATION_ERROR", "fields must be a string", field="fields")

    cols = _load("pb_collections.json")
    key = collection.strip()
    col = next((c for c in cols if isinstance(c, dict) and c.get("status") != "deleted" and (c.get("id") == key or c.get("name") == key)), None)
    if not col:
        _log(404, "Collection not found", query=q)
        return _err("NOT_FOUND", "Collection not found")

    records = _load("pb_records.json")
    rid = id.strip()

    # Be permissive: PocketBase accepts both rec_... and 15-char ids; also some callers pass field-like tokens.
    rec = next(
        (
            r
            for r in records
            if isinstance(r, dict)
            and r.get("collection_id") == col.get("id")
            and r.get("id") == rid
        ),
        None,
    )
    if not rec:
        # If id looks like a field token (as seen in audit), treat as request to return schema field definition.
        schema = col.get("schema") if isinstance(col.get("schema"), list) else []
        if isinstance(rid, str) and (rid.startswith("fld_") or rid in {f.get("name") for f in schema if isinstance(f, dict)}):
            field_def = next((f for f in schema if isinstance(f, dict) and (f.get("id") == rid or f.get("name") == rid)), None)
            if field_def is not None:
                out = {
                    "id": rid,
                    "collectionId": col.get("id"),
                    "collectionName": col.get("name"),
                    "created": col.get("created_at"),
                    "updated": col.get("updated_at"),
                    "data": {"schema": field_def} if (fields is None or "schema" in {x.strip() for x in (fields or "").split(",") if x.strip()}) else {},
                    "expand": {},
                }
                _log(200, None, collection_id=col.get("id"), record_id=rid, query=q)
                return out

        _log(404, "Record not found", collection_id=col.get("id"), record_id=rid, query=q)
        return _err("NOT_FOUND", "Record not found")

    if rec.get("status") == "deleted":
        _log(404, "Record not found", collection_id=col.get("id"), record_id=rid, query=q)
        return _err("NOT_FOUND", "Record not found")

    schema = col.get("schema") if isinstance(col.get("schema"), list) else []

    def _is_relation_field(fdef):
        if not isinstance(fdef, dict):
            return False
        t = fdef.get("type")
        # PocketBase relation field type is typically "relation"
        return t == "relation"

    def _relation_target_collection_id(fdef):
        opts = fdef.get("options") if isinstance(fdef, dict) else None
        if isinstance(opts, dict):
            return opts.get("collectionId") or opts.get("collection_id")
        return None

    def _relation_many(fdef):
        opts = fdef.get("options") if isinstance(fdef, dict) else None
        if isinstance(opts, dict):
            # PocketBase uses maxSelect; >1 implies multiple
            mx = opts.get("maxSelect")
            if isinstance(mx, int):
                return mx != 1
        return isinstance(rec.get("data", {}).get(fdef.get("name")), list)

    expand_fields = []
    if isinstance(expand, str) and expand.strip():
        expand_fields = [p.strip() for p in expand.split(",") if p.strip()]

    expand_out = {}
    if expand_fields:
        all_recs = records  # already loaded
        for ef in expand_fields:
            fdef = next((f for f in schema if isinstance(f, dict) and f.get("name") == ef), None)
            if not _is_relation_field(fdef):
                continue
            tgt_cid = _relation_target_collection_id(fdef)
            if not tgt_cid:
                continue
            tgt_col = next((c for c in cols if isinstance(c, dict) and c.get("id") == tgt_cid and c.get("status") != "deleted"), None)
            if not tgt_col:
                continue

            val = rec.get("data", {}).get(ef)
            if val is None:
                continue

            def _build_record_payload(rrow):
                return {
                    "id": rrow.get("id"),
                    "collectionId": rrow.get("collection_id"),
                    "collectionName": rrow.get("collection_name"),
                    "created": rrow.get("created_at"),
                    "updated": rrow.get("updated_at"),
                    **(rrow.get("data") if isinstance(rrow.get("data"), dict) else {}),
                }

            if isinstance(val, list):
                expanded = []
                for vid in val:
                    if not isinstance(vid, str):
                        continue
                    tr = next((rr for rr in all_recs if isinstance(rr, dict) and rr.get("collection_id") == tgt_col.get("id") and rr.get("id") == vid and rr.get("status") != "deleted"), None)
                    if tr:
                        expanded.append(_build_record_payload(tr))
                expand_out[ef] = expanded
            elif isinstance(val, str):
                tr = next((rr for rr in all_recs if isinstance(rr, dict) and rr.get("collection_id") == tgt_col.get("id") and rr.get("id") == val and rr.get("status") != "deleted"), None)
                if tr:
                    expand_out[ef] = _build_record_payload(tr)

    # fields selection: support comma list; allow system fields & data keys.
    data_obj = rec.get("data") if isinstance(rec.get("data"), dict) else {}
    base_out = {
        "id": rec.get("id"),
        "collectionId": rec.get("collection_id"),
        "collectionName": rec.get("collection_name"),
        "created": rec.get("created_at"),
        "updated": rec.get("updated_at"),
        "expand": expand_out if expand_out else {},
    }

    if isinstance(fields, str) and fields.strip():
        wanted = [p.strip() for p in fields.split(",") if p.strip()]
        allowed_system = {"id", "collectionId", "collectionName", "created", "updated", "expand"}
        out = {}
        for w in wanted:
            if w in allowed_system:
                out[w] = base_out[w]
            else:
                # data field
                if w in data_obj:
                    out[w] = data_obj.get(w)
        # Always include id/collection metadata like PocketBase does unless explicitly excluded; but keep strict to request:
        if "id" not in out:
            out["id"] = base_out["id"]
        if "collectionId" not in out:
            out["collectionId"] = base_out["collectionId"]
        if "collectionName" not in out:
            out["collectionName"] = base_out["collectionName"]
        if "created" not in out:
            out["created"] = base_out["created"]
        if "updated" not in out:
            out["updated"] = base_out["updated"]
        if expand_out and "expand" not in out:
            out["expand"] = base_out["expand"]
        _log(200, None, collection_id=col.get("id"), record_id=rec.get("id"), query=q)
        return out

    # Default: include full data merged (PocketBase record JSON style)
    full = dict(base_out)
    for k, v in data_obj.items():
        full[k] = v

    _log(200, None, collection_id=col.get("id"), record_id=rec.get("id"), query=q)
    return full

def list_records(collection, filter=None, sort=None, page=None, per_page=None, expand=None, fields=None, skip_total=None, **_extra):
    import json, os, datetime, time, re, uuid, math, statistics

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mkid(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _log(status_code, path, query=None, collection_id=None, record_id=None, error=None, started=None):
        logs = _load("pb_api_logs.json")
        ts = _now()
        dur = 0
        if started is not None:
            dur = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": _mkid("log"),
            "request_id": None,
            "method": "GET",
            "path": path,
            "query": query or None,
            "status_code": int(status_code),
            "duration_ms": int(dur),
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": collection_id,
            "record_id": record_id,
            "error": error,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("pb_api_logs.json", logs)

    started = time.time()

    if not isinstance(collection, str) or not collection.strip():
        _log(400, "/records/list", {"collection": collection}, error="Invalid collection", started=started)
        return _err("VALIDATION_ERROR", "collection must be a non-empty string")

    if filter is not None and not isinstance(filter, str):
        _log(400, "/records/list", {"collection": collection, "filter": filter}, error="Invalid filter", started=started)
        return _err("VALIDATION_ERROR", "filter must be a string")
    if sort is not None and not isinstance(sort, str):
        _log(400, "/records/list", {"collection": collection, "sort": sort}, error="Invalid sort", started=started)
        return _err("VALIDATION_ERROR", "sort must be a string")
    if expand is not None and not isinstance(expand, str):
        _log(400, "/records/list", {"collection": collection, "expand": expand}, error="Invalid expand", started=started)
        return _err("VALIDATION_ERROR", "expand must be a string")
    if fields is not None and not isinstance(fields, str):
        _log(400, "/records/list", {"collection": collection, "fields": fields}, error="Invalid fields", started=started)
        return _err("VALIDATION_ERROR", "fields must be a string")
    if skip_total is not None and not isinstance(skip_total, bool):
        _log(400, "/records/list", {"collection": collection, "skip_total": skip_total}, error="Invalid skip_total", started=started)
        return _err("VALIDATION_ERROR", "skip_total must be boolean")

    if page is None:
        page = 1
    if per_page is None:
        per_page = 30

    if not isinstance(page, int) or page < 1:
        _log(400, "/records/list", {"collection": collection, "page": page}, error="Invalid page", started=started)
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 200:
        _log(400, "/records/list", {"collection": collection, "per_page": per_page}, error="Invalid per_page", started=started)
        return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 200")

    cols = _load("pb_collections.json")
    col = None
    for c in cols:
        if c.get("status") != "deleted" and (c.get("id") == collection or c.get("name") == collection):
            col = c
            break
    if not col:
        _log(404, "/records/list", {"collection": collection, "page": page, "per_page": per_page, "filter": filter, "sort": sort}, error="Collection not found", started=started)
        return _err("NOT_FOUND", "Collection not found")

    recs = _load("pb_records.json")
    items = [r for r in recs if r.get("collection_id") == col.get("id") and r.get("status") != "deleted"]

    def _get_field(rec, key):
        if key == "id":
            return rec.get("id")
        if key == "created_at" or key == "created":
            return rec.get("created_at")
        if key == "updated_at" or key == "updated":
            return rec.get("updated_at")
        return (rec.get("data") or {}).get(key)

    # Filter (limited subset): expr with &&/||, comparisons (=, !=, >, >=, <, <=), string literals in single quotes, numbers, booleans
    def _parse_value(tok):
        t = tok.strip()
        if len(t) >= 2 and t[0] == "'" and t[-1] == "'":
            return t[1:-1]
        if t.lower() == "true":
            return True
        if t.lower() == "false":
            return False
        if re.fullmatch(r"-?\d+", t):
            return int(t)
        if re.fullmatch(r"-?\d+\.\d+", t):
            return float(t)
        # datetime-ish or bare identifier -> treat as string
        return t

    def _cmp(a, op, b):
        # Try datetime compare if ISO-like
        def _dt(x):
            if isinstance(x, str) and re.match(r"^\d{4}-\d{2}-\d{2}", x):
                try:
                    if x.endswith("Z"):
                        x2 = x[:-1]
                    else:
                        x2 = x
                    return datetime.datetime.fromisoformat(x2)
                except Exception:
                    return None
            return None

        if op in ("=", "=="):
            return a == b
        if op == "!=":
            return a != b

        adt = _dt(a)
        bdt = _dt(b)
        if adt is not None and bdt is not None:
            a2, b2 = adt, bdt
        else:
            a2, b2 = a, b
        try:
            if op == ">":
                return a2 > b2
            if op == ">=":
                return a2 >= b2
            if op == "<":
                return a2 < b2
            if op == "<=":
                return a2 <= b2
        except Exception:
            return False
        return False

    def _eval_simple(rec, expr):
        m = re.match(r"^\s*([A-Za-z_][A-Za-z0-9_\.]*)\s*(=|==|!=|>=|<=|>|<)\s*(.+?)\s*$", expr)
        if not m:
            return None  # signal malformed
        key, op, raw = m.group(1), m.group(2), m.group(3)
        if key.startswith("data."):
            key = key[5:]
        val = _get_field(rec, key)
        rhs = _parse_value(raw)
        return _cmp(val, op, rhs)

    def _apply_filter(rows, fexpr):
        if not fexpr or not fexpr.strip():
            return rows
        # Split on || first, then &&; no parentheses support
        or_parts = [p.strip() for p in fexpr.split("||")]
        out = []
        for rec in rows:
            ok_any = False
            for opart in or_parts:
                and_parts = [p.strip() for p in opart.split("&&")]
                ok_all = True
                for apart in and_parts:
                    if not apart:
                        continue
                    res = _eval_simple(rec, apart)
                    if res is None:
                        return None  # malformed
                    if not res:
                        ok_all = False
                        break
                if ok_all:
                    ok_any = True
                    break
            if ok_any:
                out.append(rec)
        return out

    if filter:
        filtered = _apply_filter(items, filter)
        if filtered is None:
            _log(400, "/records/list", {"collection": collection, "filter": filter}, collection_id=col.get("id"), error="Malformed filter", started=started)
            return _err("VALIDATION_ERROR", "Malformed filter expression")
        items = filtered

    # Sort
    sort_fields = []
    if sort and sort.strip():
        try:
            for part in [p.strip() for p in sort.split(",") if p.strip()]:
                direction = 1
                name = part
                if part[0] == "-":
                    direction = -1
                    name = part[1:].strip()
                elif part[0] == "+":
                    name = part[1:].strip()
                if not name:
                    raise ValueError("empty sort name")
                sort_fields.append((name, direction))
        except Exception:
            _log(400, "/records/list", {"collection": collection, "sort": sort}, collection_id=col.get("id"), error="Malformed sort", started=started)
            return _err("VALIDATION_ERROR", "Malformed sort parameter")
    else:
        sort_fields = [("created_at", -1)]

    def _sort_key(rec):
        key = []
        for name, direction in sort_fields:
            v = _get_field(rec, name)
            # Normalize None for stable sorting
            key.append(v)
        return tuple(key)

    # Python's sort doesn't support per-field direction directly; apply stable sorts reversed.
    for name, direction in reversed(sort_fields):
        items.sort(key=lambda r: (_get_field(r, name) is None, _get_field(r, name)), reverse=(direction == -1))

    total = None
    if not skip_total:
        total = len(items)

    start = (page - 1) * per_page
    end = start + per_page
    page_items = items[start:end]

    # Reuse fetch_record shaping for each row (without extra disk writes)
    # Compute expand from schema similarly
    schema = col.get("schema") or []
    field_defs = {}
    for f in schema:
        if isinstance(f, dict) and isinstance(f.get("name"), str):
            field_defs[f["name"]] = f

    expand_fields = []
    if expand:
        try:
            expand_fields = [p.strip() for p in expand.split(",") if p.strip()]
        except Exception:
            _log(400, "/records/list", {"collection": collection, "expand": expand}, collection_id=col.get("id"), error="Malformed expand", started=started)
            return _err("VALIDATION_ERROR", "Malformed expand parameter")

    requested_fields = None
    if fields:
        try:
            requested_fields = [p.strip() for p in fields.split(",") if p.strip()]
        except Exception:
            _log(400, "/records/list", {"collection": collection, "fields": fields}, collection_id=col.get("id"), error="Malformed fields", started=started)
            return _err("VALIDATION_ERROR", "Malformed fields parameter")

    def _expand_for_record(rec):
        if not expand_fields:
            return None
        expand_out = {}
        for ef in expand_fields:
            top = ef.split(".")[0].strip()
            if not top:
                continue
            fdef = field_defs.get(top)
            if not fdef or fdef.get("type") != "relation":
                continue
            options = fdef.get("options") if isinstance(fdef.get("options"), dict) else {}
            target_cid = options.get("collectionId") or options.get("collection_id")
            target_cname = options.get("collectionName") or options.get("collection_name")
            target_col = None
            if target_cid or target_cname:
                for c in cols:
                    if c.get("status") != "deleted" and ((target_cid and c.get("id") == target_cid) or (target_cname and c.get("name") == target_cname)):
                        target_col = c
                        break
            if not target_col:
                continue

            value = (rec.get("data") or {}).get(top)
            if value is None:
                expand_out[top] = None
                continue

            def _find_record(rid):
                for rr in recs:
                    if rr.get("collection_id") == target_col.get("id") and rr.get("id") == rid and rr.get("status") != "deleted":
                        return rr
                return None

            if isinstance(value, str):
                tr = _find_record(value)
                expand_out[top] = None if not tr else {
                    "id": tr.get("id"),
                    "collectionId": tr.get("collection_id"),
                    "collectionName": tr.get("collection_name"),
                    "created": tr.get("created_at"),
                    "updated": tr.get("updated_at"),
                    **(tr.get("data") or {}),
                }
            elif isinstance(value, list):
                expanded_list = []
                for rid in value:
                    if isinstance(rid, str):
                        tr = _find_record(rid)
                        if tr:
                            expanded_list.append({
                                "id": tr.get("id"),
                                "collectionId": tr.get("collection_id"),
                                "collectionName": tr.get("collection_name"),
                                "created": tr.get("created_at"),
                                "updated": tr.get("updated_at"),
                                **(tr.get("data") or {}),
                            })
                expand_out[top] = expanded_list
        return expand_out or None

    def _shape(rec):
        out = {
            "id": rec.get("id"),
            "collectionId": rec.get("collection_id"),
            "collectionName": rec.get("collection_name"),
            "created": rec.get("created_at"),
            "updated": rec.get("updated_at"),
        }
        for k, v in (rec.get("data") or {}).items():
            out[k] = v
        ex = _expand_for_record(rec)
        if ex:
            out["expand"] = ex

        if requested_fields is not None:
            allowed = set(out.keys())
            filtered = {}
            for f in requested_fields:
                if f not in allowed:
                    return None, f
                filtered[f] = out[f]
            out = filtered
        return out, None

    shaped = []
    for r in page_items:
        o, bad = _shape(r)
        if bad:
            _log(400, "/records/list", {"collection": collection, "fields": fields}, collection_id=col.get("id"), error=f"Unknown field in fields: {bad}", started=started)
            return _err("VALIDATION_ERROR", f"Unknown field requested: {bad}")
        shaped.append(o)

    resp = {
        "page": page,
        "per_page": per_page,
        "items": shaped,
    }
    if not skip_total:
        resp["total_items"] = total
        resp["total_pages"] = int(math.ceil(total / per_page)) if per_page else 0

    _log(200, "/records/list", {"collection": collection, "page": page, "per_page": per_page, "filter": filter, "sort": sort, "expand": expand, "fields": fields, "skip_total": skip_total}, collection_id=col.get("id"), started=started)
    return resp

def create_record(collection, data, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, collection_id=None, record_id=None, query=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "POST",
                "path": "/api/records/create",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id,
                "record_id": record_id,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"collection": collection}

    if not isinstance(collection, str) or not collection.strip():
        _log(400, "collection must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "collection must be a non-empty string", field="collection")
    if not isinstance(data, dict):
        _log(400, "data must be an object", query=q)
        return _err("VALIDATION_ERROR", "data must be an object", field="data")

    cols = _load("pb_collections.json")
    key = collection.strip()
    col = next((c for c in cols if isinstance(c, dict) and c.get("status") != "deleted" and (c.get("id") == key or c.get("name") == key)), None)
    if not col:
        _log(404, "Collection not found", query=q)
        return _err("NOT_FOUND", "Collection not found")

    if col.get("status") != "active":
        _log(409, "Collection is not active", collection_id=col.get("id"), query=q)
        return _err("CONFLICT", "Collection is not active", rule="pb_collections.status must be 'active'")
    if col.get("type") == "view":
        _log(409, "Cannot create records in a view collection", collection_id=col.get("id"), query=q)
        return _err("CONFLICT", "Cannot create records in a view collection", rule="pb_collections.type != 'view'")

    schema = col.get("schema") if isinstance(col.get("schema"), list) else []

    # validate: allow unknown fields (PocketBase typically rejects unknown), but keep lenient to avoid false negatives.
    # enforce only required fields if marked required and basic types when obvious.
    missing_required = None
    for f in schema:
        if not isinstance(f, dict):
            continue
        fname = f.get("name")
        if not isinstance(fname, str) or not fname:
            continue
        required = f.get("required") is True
        if required and fname not in data:
            missing_required = fname
            break
    if missing_required:
        _log(400, f"Missing required field: {missing_required}", collection_id=col.get("id"), query=q)
        return _err("VALIDATION_ERROR", f"Missing required field: {missing_required}", field=missing_required, rule="required field missing")

    # unique constraints (best-effort): fields in schema with unique=true
    unique_fields = []
    for f in schema:
        if isinstance(f, dict) and f.get("unique") is True and isinstance(f.get("name"), str):
            unique_fields.append(f["name"])

    records = _load("pb_records.json")
    for uf in unique_fields:
        if uf in data:
            for r in records:
                if not isinstance(r, dict):
                    continue
                if r.get("collection_id") != col.get("id"):
                    continue
                if r.get("status") == "deleted":
                    continue
                rdata = r.get("data") if isinstance(r.get("data"), dict) else {}
                if rdata.get(uf) == data.get(uf):
                    _log(409, f"Unique constraint violated: {uf}", collection_id=col.get("id"), query=q)
                    return _err("CONFLICT", f"Unique constraint violated: {uf}", field=uf, rule="unique")

    now = _now_iso()
    new_id = _gen_id("rec")
    row = {
        "id": new_id,
        "collection_id": col.get("id"),
        "collection_name": col.get("name"),
        "data": data,
        "expand": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    records.append(row)
    _save("pb_records.json", records)

    out = {
        "id": row["id"],
        "collectionId": row["collection_id"],
        "collectionName": row["collection_name"],
        "created": row["created_at"],
        "updated": row["updated_at"],
        **(row["data"] if isinstance(row["data"], dict) else {}),
        "expand": {},
    }
    _log(200, None, collection_id=col.get("id"), record_id=row["id"], query=q)
    return out

def update_record(collection, id, data, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mkid(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24]}"

    def _log(status_code, path, query=None, collection_id=None, record_id=None, error=None, started=None):
        logs = _load("pb_api_logs.json")
        ts = _now()
        dur = 0
        if started is not None:
            dur = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": _mkid("log"),
            "request_id": None,
            "method": "PATCH",
            "path": path,
            "query": query or None,
            "status_code": int(status_code),
            "duration_ms": int(dur),
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": collection_id,
            "record_id": record_id,
            "error": error,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("pb_api_logs.json", logs)

    started = time.time()

    if not isinstance(collection, str) or not collection.strip():
        _log(400, "/records/update", {"collection": collection, "id": id}, error="Invalid collection", started=started)
        return _err("VALIDATION_ERROR", "collection must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _log(400, "/records/update", {"collection": collection, "id": id}, error="Invalid id", started=started)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(data, dict):
        _log(400, "/records/update", {"collection": collection, "id": id}, error="Invalid data", started=started)
        return _err("VALIDATION_ERROR", "data must be an object")

    cols = _load("pb_collections.json")
    col = None
    for c in cols:
        if c.get("status") != "deleted" and (c.get("id") == collection or c.get("name") == collection):
            col = c
            break
    if not col:
        _log(404, "/records/update", {"collection": collection, "id": id}, error="Collection not found", started=started)
        return _err("NOT_FOUND", "Collection not found")

    if col.get("status") != "active":
        _log(409, "/records/update", {"collection": collection, "id": id}, collection_id=col.get("id"), record_id=id, error="Collection not active", started=started)
        return _err("INVALID_TRANSITION", "Cannot update records in a non-active collection")

    schema = col.get("schema") or []
    field_defs = {}
    for f in schema:
        if isinstance(f, dict) and isinstance(f.get("name"), str):
            field_defs[f["name"]] = f

    # Validate field names
    for k in data.keys():
        if k not in field_defs:
            _log(400, "/records/update", {"collection": collection, "id": id}, collection_id=col.get("id"), record_id=id, error=f"Unknown field: {k}", started=started)
            return _err("VALIDATION_ERROR", f"Unknown field: {k}")

    def _type_ok(ftype, value, fdef):
        if value is None:
            return True
        if ftype in ("text", "editor", "url", "email", "json"):
            return isinstance(value, str) or (ftype == "json" and isinstance(value, (dict, list, str, int, float, bool)))
        if ftype in ("number",):
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        if ftype in ("bool", "boolean"):
            return isinstance(value, bool)
        if ftype in ("date",):
            return isinstance(value, str)
        if ftype in ("relation",):
            if isinstance(value, str):
                return True
            if isinstance(value, list) and all(isinstance(x, str) for x in value):
                return True
            return False
        if ftype in ("select",):
            opts = fdef.get("options") if isinstance(fdef.get("options"), dict) else {}
            max_sel = opts.get("maxSelect")
            vals = opts.get("values")
            allowed = set([str(v) for v in vals]) if isinstance(vals, list) else None
            if max_sel and max_sel != 1:
                if not isinstance(value, list) or not all(isinstance(x, str) for x in value):
                    return False
                if allowed is not None and any(v not in allowed for v in value):
                    return False
                return True
            else:
                if not isinstance(value, str):
                    return False
                if allowed is not None and value not in allowed:
                    return False
                return True
        if ftype in ("file",):
            if isinstance(value, str):
                return True
            if isinstance(value, list) and all(isinstance(x, str) for x in value):
                return True
            return False
        return True

    # Validate types
    for name, val in data.items():
        fdef = field_defs.get(name)
        ftype = fdef.get("type") if isinstance(fdef, dict) else None
        if ftype and not _type_ok(ftype, val, fdef):
            _log(400, "/records/update", {"collection": collection, "id": id}, collection_id=col.get("id"), record_id=id, error=f"Invalid type for field: {name}", started=started)
            return _err("VALIDATION_ERROR", f"Invalid value type for field: {name}")

    recs = _load("pb_records.json")
    idx = None
    rec = None
    for i, r in enumerate(recs):
        if r.get("collection_id") == col.get("id") and r.get("id") == id:
            idx = i
            rec = r
            break
    if not rec or rec.get("status") == "deleted":
        _log(404, "/records/update", {"collection": collection, "id": id}, collection_id=col.get("id"), record_id=id, error="Record not found", started=started)
        return _err("NOT_FOUND", "Record not found")

    # Enforce unique constraints for updated fields
    active_recs = [r for r in recs if r.get("collection_id") == col.get("id") and r.get("status") != "deleted" and r.get("id") != id]
    for name, fdef in field_defs.items():
        if fdef.get("unique") is True and name in data:
            val = data.get(name)
            for r in active_recs:
                if (r.get("data") or {}).get(name) == val:
                    _log(409, "/records/update", {"collection": collection, "id": id}, collection_id=col.get("id"), record_id=id, error=f"Unique constraint failed: {name}", started=started)
                    return _err("CONFLICT", f"Unique constraint failed for field: {name}")

    # Apply update
    new_data = dict(rec.get("data") or {})
    new_data.update(data)

    rec["data"] = new_data
    rec["updated_at"] = _now()
    recs[idx] = rec
    _save("pb_records.json", recs)

    out = {
        "id": rec.get("id"),
        "collectionId": rec.get("collection_id"),
        "collectionName": rec.get("collection_name"),
        "created": rec.get("created_at"),
        "updated": rec.get("updated_at"),
        **(rec.get("data") or {}),
    }

    _log(200, "/records/update", {"collection": collection, "id": id}, collection_id=col.get("id"), record_id=id, started=started)
    return {"record": out}

def list_collections(type=None, system=None, status=None, page=None, per_page=None, sort=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets, string
        alphabet = string.ascii_lowercase + string.digits
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(26))

    def _log(status_code, error=None):
        logs = _load("pb_api_logs.json")
        now = _now()
        row = {
            "id": _gen_id("log"),
            "request_id": None,
            "method": "GET",
            "path": "/collections",
            "query": {"type": type, "system": system, "status": status, "page": page, "per_page": per_page, "sort": sort},
            "status_code": int(status_code),
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": None,
            "record_id": None,
            "error": error,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("pb_api_logs.json", logs)

    # Validate
    if type is not None:
        if not isinstance(type, str) or type not in ("base", "auth", "view"):
            _log(400, "Invalid `type`.")
            return _err("VALIDATION_ERROR", "Invalid `type`.", field="type")
    if system is not None and not isinstance(system, bool):
        _log(400, "Invalid `system`.")
        return _err("VALIDATION_ERROR", "Invalid `system`.", field="system")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(400, "Invalid `status`.")
            return _err("VALIDATION_ERROR", "Invalid `status`.", field="status")
    if page is None:
        page = 1
    if per_page is None:
        per_page = 30
    if not isinstance(page, int) or page < 1:
        _log(400, "Invalid `page`.")
        return _err("VALIDATION_ERROR", "Invalid `page`.", field="page")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 500:
        _log(400, "Invalid `per_page`.")
        return _err("VALIDATION_ERROR", "Invalid `per_page`.", field="per_page")

    if sort is not None and (not isinstance(sort, str) or not sort.strip()):
        _log(400, "Invalid `sort`.")
        return _err("VALIDATION_ERROR", "Invalid `sort`.", field="sort")

    colls = _load("pb_collections.json")
    if not colls:
        # No ambient auth context to enumerate.
        _log(401, "No authorized context available.")
        return _err("UNAUTHORIZED", "Unauthorized.")

    # Base rule: status != 'deleted' unless caller explicitly requests status='deleted'
    rows = []
    for c in colls:
        if status is None:
            if c.get("status") == "deleted":
                continue
        else:
            if c.get("status") != status:
                continue
        if type is not None and c.get("type") != type:
            continue
        if system is not None and bool(c.get("system")) != system:
            continue
        rows.append(c)

    # Sorting
    def _coerce(v):
        if v is None:
            return ""
        return v

    sort_spec = sort.strip() if isinstance(sort, str) and sort.strip() else "name"
    fields = [s.strip() for s in sort_spec.split(",") if s.strip()]
    # stable multi-sort: apply reversed
    for spec in reversed(fields):
        desc = spec.startswith("-")
        key = spec[1:] if spec.startswith(("-", "+")) else spec
        def kfun(r, _key=key):
            if _key in ("id", "name", "type", "status", "created_at", "updated_at"):
                return _coerce(r.get(_key))
            return ""
        rows.sort(key=kfun, reverse=desc)

    total = len(rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_items = rows[start:end]
    has_more = end < total

    # Return minimal schema metadata per row (like PocketBase list collections)
    items = []
    for c in page_items:
        items.append({
            "id": c.get("id"),
            "name": c.get("name"),
            "type": c.get("type"),
            "system": c.get("system"),
            "status": c.get("status"),
            "created_at": c.get("created_at"),
            "updated_at": c.get("updated_at"),
        })

    _log(200, None)
    return {
        "page": page,
        "per_page": per_page,
        "total_items": total,
        "total_pages": (total + per_page - 1) // per_page if per_page else 0,
        "items": items,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
    }

def upload_file(collection, record_id, field, filename, content_type, content, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets, string
        alphabet = string.ascii_lowercase + string.digits
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(26))

    def _log(status_code, error=None, collection_id=None, record_id_for_log=None):
        logs = _load("pb_api_logs.json")
        now = _now()
        row = {
            "id": _gen_id("log"),
            "request_id": None,
            "method": "POST",
            "path": "/files/upload",
            "query": {"collection": collection, "record_id": record_id, "field": field, "filename": filename, "content_type": content_type},
            "status_code": int(status_code),
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": collection_id,
            "record_id": record_id_for_log,
            "error": error,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("pb_api_logs.json", logs)

    # Validate required params types
    for k, v in (("collection", collection), ("record_id", record_id), ("field", field), ("filename", filename), ("content_type", content_type), ("content", content)):
        if not isinstance(v, str) or not v.strip():
            _log(400, f"Invalid `{k}`.")
            return _err("VALIDATION_ERROR", f"Invalid `{k}`.", field=k)

    colls = _load("pb_collections.json")
    if not colls:
        _log(401, "No authorized context available.")
        return _err("UNAUTHORIZED", "Unauthorized.")

    s = collection.strip()
    coll = None
    for c in colls:
        if c.get("id") == s or c.get("name") == s:
            coll = c
            break
    if not coll or coll.get("status") == "deleted":
        _log(404, "Collection not found.")
        return _err("NOT_FOUND", "Collection not found.")
    if coll.get("status") != "active":
        _log(409, "Collection is not active.", collection_id=coll.get("id"))
        return _err("CONFLICT", "Collection is not active.")
    if coll.get("type") == "view":
        _log(409, "Cannot upload files to view collections.", collection_id=coll.get("id"))
        return _err("CONFLICT", "Cannot upload files to view collections.")

    records = _load("pb_records.json")
    rec = None
    for r in records:
        if r.get("id") == record_id and (r.get("collection_id") == coll.get("id") or r.get("collection_name") == coll.get("name")):
            rec = r
            break
    if not rec:
        _log(404, "Record not found.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("NOT_FOUND", "Record not found.")
    if rec.get("status") == "deleted":
        _log(409, "Record is deleted.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("INVALID_TRANSITION", "Cannot upload to a deleted record.")
    if rec.get("collection_id") != coll.get("id"):
        _log(409, "Record/collection mismatch.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("CONFLICT", "Record/collection mismatch.")

    schema = coll.get("schema") if isinstance(coll.get("schema"), list) else []
    fdef = None
    for fd in schema:
        if isinstance(fd, dict) and fd.get("name") == field:
            fdef = fd
            break
    if not fdef:
        _log(400, "Field not found in collection schema.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("VALIDATION_ERROR", "Field not found in collection schema.", field="field")
    ftype = fdef.get("type")
    if ftype not in ("file", "files"):
        # treat only PocketBase-like file field types as file-capable
        _log(400, "Target field is not a file field.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("VALIDATION_ERROR", "Target field is not a file field.", field="field")

    # Decode content (base64 preferred; if not base64, accept as utf-8 bytes)
    raw = None
    cstr = content.strip()
    try:
        raw = base64.b64decode(cstr, validate=True)
    except Exception:
        try:
            raw = cstr.encode("utf-8")
        except Exception:
            _log(400, "Content cannot be decoded.", collection_id=coll.get("id"), record_id_for_log=record_id)
            return _err("VALIDATION_ERROR", "Content cannot be decoded.", field="content")

    size = len(raw)
    if size < 0 or size > 536870912:
        _log(400, "File too large.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("VALIDATION_ERROR", "File too large.", field="content", max_bytes=536870912)

    options = fdef.get("options") if isinstance(fdef.get("options"), dict) else {}
    max_size = options.get("maxSize")
    if isinstance(max_size, int) and max_size > 0 and size > max_size:
        _log(400, "File exceeds field maxSize.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("VALIDATION_ERROR", "File exceeds field maxSize.", field="content", max_bytes=max_size)

    # Determine maxSelect / single vs multiple
    max_select = options.get("maxSelect")
    multiple = True if ftype == "files" else False
    if isinstance(max_select, int) and max_select == 1:
        multiple = False
    if not isinstance(rec.get("data"), dict):
        rec["data"] = {}

    current_val = rec["data"].get(field)
    current_list = []
    if multiple:
        if current_val is None:
            current_list = []
        elif isinstance(current_val, list) and all(isinstance(x, str) for x in current_val):
            current_list = list(current_val)
        else:
            _log(400, "Existing field value has invalid type.", collection_id=coll.get("id"), record_id_for_log=record_id)
            return _err("VALIDATION_ERROR", "Existing field value has invalid type.", field="field")
    else:
        if current_val is None:
            current_list = []
        elif isinstance(current_val, str):
            current_list = [current_val]
        else:
            _log(400, "Existing field value has invalid type.", collection_id=coll.get("id"), record_id_for_log=record_id)
            return _err("VALIDATION_ERROR", "Existing field value has invalid type.", field="field")

    if isinstance(max_select, int) and max_select > 0:
        if multiple:
            if len(current_list) + 1 > max_select:
                _log(400, "Too many files for field.", collection_id=coll.get("id"), record_id_for_log=record_id)
                return _err("VALIDATION_ERROR", "Too many files for field.", field="field", max_select=max_select)
        else:
            # single: always replace
            pass

    # Generate stored filename (unique per record/field)
    import secrets
    base = os.path.basename(filename.strip()) or "file"
    _, ext = os.path.splitext(base)
    token = secrets.token_hex(12)
    stored_filename = f"{token}{ext}"

    files = _load("pb_files.json")
    # Ensure uniqueness (record_id, field_name, stored_filename)
    if any((f.get("record_id") == rec.get("id") and f.get("field_name") == field and f.get("stored_filename") == stored_filename) for f in files):
        stored_filename = f"{token}_{secrets.token_hex(4)}{ext}"

    # Write blob to local filesystem backend
    storage_backend = "local_fs"
    files_root = os.path.join(_DB, "files")
    rel_path = os.path.join(coll.get("id") or "collection", rec.get("id") or "record")
    abs_dir = os.path.join(files_root, rel_path)
    try:
        os.makedirs(abs_dir, exist_ok=True)
    except Exception:
        _log(500, "Unable to create storage directory.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("CONFLICT", "Unable to create storage directory.")
    abs_path = os.path.join(abs_dir, stored_filename)
    try:
        with open(abs_path, "wb") as f:
            f.write(raw)
    except Exception:
        _log(500, "Unable to store file.", collection_id=coll.get("id"), record_id_for_log=record_id)
        return _err("CONFLICT", "Unable to store file.")

    sha = hashlib.sha256(raw).hexdigest()

    now = _now()
    file_row = {
        "id": _gen_id("file"),
        "collection_id": coll.get("id"),
        "record_id": rec.get("id"),
        "field_name": field,
        "original_filename": base,
        "stored_filename": stored_filename,
        "content_type": content_type.strip(),
        "size_bytes": int(size),
        "sha256": sha,
        "storage_backend": storage_backend,
        "storage_path": os.path.join(rel_path, stored_filename).replace("\\", "/"),
        "public_url": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    files.append(file_row)

    # Update record field value
    if multiple:
        new_list = current_list + [stored_filename]
        rec["data"][field] = new_list
    else:
        rec["data"][field] = stored_filename

    rec["updated_at"] = now

    # Persist
    _save("pb_files.json", files)
    _save("pb_records.json", records)

    # Return updated record (denormalized)
    out = {
        "id": rec.get("id"),
        "collection_id": rec.get("collection_id"),
        "collection_name": rec.get("collection_name"),
        "data": rec.get("data"),
        "status": rec.get("status"),
        "created_at": rec.get("created_at"),
        "updated_at": rec.get("updated_at"),
    }

    _log(200, None, collection_id=coll.get("id"), record_id_for_log=rec.get("id"))
    return {"record": out, "file": {k: file_row.get(k) for k in ("id", "field_name", "original_filename", "stored_filename", "content_type", "size_bytes", "storage_backend", "storage_path", "status", "created_at")}}

def download_file(collection, record_id, field, filename, **_extra):
    import json, os, datetime, time, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, collection_id=None, record_id_for_log=None, query=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "GET",
                "path": "/api/files/download",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id,
                "record_id": record_id_for_log,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"collection": collection, "record_id": record_id, "field": field, "filename": filename}

    for k, v in (("collection", collection), ("record_id", record_id), ("field", field), ("filename", filename)):
        if not isinstance(v, str) or not v.strip():
            _log(400, f"{k} must be a non-empty string", query=q)
            return _err("VALIDATION_ERROR", f"{k} must be a non-empty string", field=k)

    cols = _load("pb_collections.json")
    ckey = collection.strip()
    col = next((c for c in cols if isinstance(c, dict) and c.get("status") != "deleted" and (c.get("id") == ckey or c.get("name") == ckey)), None)
    if not col:
        _log(404, "Collection not found.", query=q)
        return _err("NOT_FOUND", "Collection not found.")

    records = _load("pb_records.json")
    rid = record_id.strip()
    rec = next((r for r in records if isinstance(r, dict) and r.get("collection_id") == col.get("id") and r.get("id") == rid), None)
    if not rec or rec.get("status") == "deleted":
        _log(404, "Record not found.", collection_id=col.get("id"), record_id_for_log=rid, query=q)
        return _err("NOT_FOUND", "Record not found.")

    schema = col.get("schema") if isinstance(col.get("schema"), list) else []
    fname = field.strip()
    fdef = next((f for f in schema if isinstance(f, dict) and f.get("name") == fname), None)
    if not fdef:
        _log(400, "field does not exist in collection schema", collection_id=col.get("id"), record_id_for_log=rid, query=q)
        return _err("VALIDATION_ERROR", "field does not exist in collection schema", field="field")

    ftype = fdef.get("type")
    # Accept typical file types; PocketBase uses "file"
    if ftype not in ("file", "files"):
        # Some schemas store file as type="file" only; treat "files" as multi.
        _log(400, "field is not a file field", collection_id=col.get("id"), record_id_for_log=rid, query=q)
        return _err("VALIDATION_ERROR", "field is not a file field", field="field", rule="field must be file-capable")

    fval = (rec.get("data") if isinstance(rec.get("data"), dict) else {}).get(fname)
    wanted = filename.strip()
    if isinstance(fval, list):
        if wanted not in [x for x in fval if isinstance(x, str)]:
            _log(404, "Requested filename not present on record field", collection_id=col.get("id"), record_id_for_log=rid, query=q)
            return _err("NOT_FOUND", "Requested filename not present on record field")
    elif isinstance(fval, str):
        if wanted != fval:
            _log(404, "Requested filename not present on record field", collection_id=col.get("id"), record_id_for_log=rid, query=q)
            return _err("NOT_FOUND", "Requested filename not present on record field")
    else:
        _log(404, "Requested filename not present on record field", collection_id=col.get("id"), record_id_for_log=rid, query=q)
        return _err("NOT_FOUND", "Requested filename not present on record field")

    files = _load("pb_files.json")
    frow = next(
        (
            f
            for f in files
            if isinstance(f, dict)
            and f.get("collection_id") == col.get("id")
            and f.get("record_id") == rid
            and f.get("field_name") == fname
            and (f.get("stored_filename") == wanted or f.get("original_filename") == wanted)
        ),
        None,
    )
    if not frow or frow.get("status") != "active":
        _log(404, "File not found.", collection_id=col.get("id"), record_id_for_log=rid, query=q)
        return _err("NOT_FOUND", "File not found.")

    backend = frow.get("storage_backend")
    spath = frow.get("storage_path")
    if not isinstance(spath, str) or not spath:
        _log(409, "File storage_path missing", collection_id=col.get("id"), record_id_for_log=rid, query=q)
        return _err("CONFLICT", "File storage_path missing")

    # Construct URL (offline, unsigned placeholder but derived deterministically from backend/path)
    if backend == "local_fs":
        url = "file://" + urllib.parse.quote("/pb_data/" + spath.lstrip("/"))
    elif backend == "s3_compatible":
        url = "s3://bucket/" + urllib.parse.quote(spath.lstrip("/"))
    else:
        _log(409, "Unknown storage backend", collection_id=col.get("id"), record_id_for_log=rid, query=q)
        return _err("CONFLICT", "Unknown storage backend")

    out = {
        "url": url,
        "file": {
            "id": frow.get("id"),
            "collection_id": frow.get("collection_id"),
            "record_id": frow.get("record_id"),
            "field_name": frow.get("field_name"),
            "original_filename": frow.get("original_filename"),
            "stored_filename": frow.get("stored_filename"),
            "content_type": frow.get("content_type"),
            "size_bytes": frow.get("size_bytes"),
            "sha256": frow.get("sha256"),
            "storage_backend": frow.get("storage_backend"),
            "storage_path": frow.get("storage_path"),
            "public_url": frow.get("public_url"),
            "status": frow.get("status"),
            "created_at": frow.get("created_at"),
            "updated_at": frow.get("updated_at"),
        },
    }

    _log(200, None, collection_id=col.get("id"), record_id_for_log=rid, query=q)
    return out

def create_migration(name, **_extra):
    import json, os, datetime, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        def enc(v, n):
            s = ""
            for _ in range(n):
                s = alphabet[v % 32] + s
                v //= 32
            return s
        return enc(ts, 10) + "".join(random.choice(alphabet) for _ in range(16))

    def _log(status_code, path, method="POST", query=None, err=None):
        logs = _load("pb_api_logs.json")
        logs.append({
            "id": "pblog_" + _ulid(),
            "request_id": None,
            "method": method,
            "path": path,
            "query": query if isinstance(query, dict) else ({} if query is None else {"_raw": str(query)}),
            "status_code": int(status_code),
            "duration_ms": int(max(0, min(3600000, round((time.time() - start) * 1000)))),
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": None,
            "record_id": None,
            "error": err,
            "created_at": now,
            "updated_at": now,
        })
        _save("pb_api_logs.json", logs)

    # Validate name
    if name is None or not isinstance(name, str) or not name.strip():
        _log(400, "/migrations", err="name is required")
        return _err("VALIDATION_ERROR", "name is required")
    raw = name.strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 _.-]{0,127}", raw):
        _log(400, "/migrations", err="unsupported characters in name")
        return _err("VALIDATION_ERROR", "Unsupported characters in name")

    # Resolve active migrations_dir from config row
    migrations = _load("pb_migrations.json")
    cfg = next((r for r in migrations if r.get("id") == "pbmigcfg_active"), None)
    migrations_dir = cfg.get("migrations_dir") if isinstance(cfg, dict) else None
    if not migrations_dir:
        # Default to allowed base
        migrations_dir = os.path.join(_DB, "migrations")
        try:
            os.makedirs(migrations_dir, exist_ok=True)
        except Exception:
            _log(403, "/migrations", err="migrations directory not configured/creatable")
            return _err("UNAUTHORIZED", "Migrations directory not configured")

    # Ensure under allowed base
    allowed_base = os.path.realpath(os.path.join(_DB, "migrations"))
    try:
        mig_real = os.path.realpath(migrations_dir)
        if not (mig_real == allowed_base or mig_real.startswith(allowed_base + os.sep)):
            _log(403, "/migrations", err="migrations_dir outside allowed base path")
            return _err("UNAUTHORIZED", "Not allowed to create migrations in this directory")
    except Exception:
        _log(400, "/migrations", err="invalid migrations_dir")
        return _err("VALIDATION_ERROR", "Invalid migrations_dir")

    # Slugify name to filename-friendly
    slug = re.sub(r"[^A-Za-z0-9]+", "_", raw).strip("_").lower()
    if not slug:
        _log(400, "/migrations", err="name produces empty slug")
        return _err("VALIDATION_ERROR", "Invalid name")

    # Generate timestamped filename; ensure uniqueness within migrations_dir
    # Format: YYYYMMDDHHMMSS_<slug>.json
    ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
    base_filename = f"{ts}_{slug}.json"
    existing = {r.get("filename") for r in migrations if r.get("migrations_dir") == mig_real}
    filename = base_filename
    i = 1
    while filename in existing:
        filename = f"{ts}_{slug}_{i}.json"
        i += 1
        if i > 9999:
            _log(409, "/migrations", err="could not generate unique filename")
            return _err("CONFLICT", "Migration filename conflict")

    # Create migration row
    mig_id = "pbmig_" + _ulid()
    row = {
        "id": mig_id,
        "migrations_dir": mig_real,
        "filename": filename,
        "name": raw,
        "kind": "empty",
        "target_collection_id": None,
        "target_collection_name": None,
        "payload": None,
        "up_sql_or_code": None,
        "down_sql_or_code": None,
        "status": "draft",
        "applied_at": None,
        "reverted_at": None,
        "last_error": None,
        "created_at": now,
        "updated_at": now,
    }

    migrations.append(row)
    _save("pb_migrations.json", migrations)

    # Create a corresponding file on disk to reflect real behavior
    try:
        os.makedirs(mig_real, exist_ok=True)
        path = os.path.join(mig_real, filename)
        if os.path.exists(path):
            _log(409, "/migrations", err="migration file already exists")
            return _err("CONFLICT", "Migration already exists")
        with open(path, "w", encoding="utf-8") as f:
            json.dump({"id": mig_id, "name": raw, "kind": "empty", "up": None, "down": None}, f, ensure_ascii=False, indent=2)
    except Exception:
        # Mark failed (no blanket except elsewhere; this is expected IO risk)
        row["status"] = "failed"
        row["last_error"] = "Failed to write migration file"
        row["updated_at"] = now
        _save("pb_migrations.json", migrations)
        _log(400, "/migrations", err="failed to write migration file")
        return _err("VALIDATION_ERROR", "Failed to write migration file")

    _log(201, "/migrations")
    return {
        "migration": row
    }

def create_collection_migration(name, collection, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _slugify(s):
        s = (s or "").strip().lower()
        s = re.sub(r"[^a-z0-9]+", "_", s)
        s = re.sub(r"_+", "_", s).strip("_")
        return s or "migration"

    def _log(status_code, error=None, query=None, migration_id=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "POST",
                "path": "/api/migrations/create-collection",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": None,
                "record_id": migration_id,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"name": name, "collection": collection}

    if not isinstance(name, str) or not name.strip():
        _log(400, "name is required", query=q)
        return _err("VALIDATION_ERROR", "name is required", field="name")
    if not isinstance(collection, dict):
        _log(400, "collection must be an object", query=q)
        return _err("VALIDATION_ERROR", "collection must be an object", field="collection")

    cname = collection.get("name")
    ctype = collection.get("type")
    cschema = collection.get("schema")

    if not isinstance(cname, str) or not cname.strip():
        _log(400, "collection.name is required", query=q)
        return _err("VALIDATION_ERROR", "collection.name is required", field="collection.name")
    if ctype not in ("base", "auth", "view"):
        _log(400, "collection.type must be one of: base, auth, view", query=q)
        return _err("VALIDATION_ERROR", "collection.type must be one of: base, auth, view", field="collection.type")
    if not isinstance(cschema, list):
        _log(400, "collection.schema must be an array", query=q)
        return _err("VALIDATION_ERROR", "collection.schema must be an array", field="collection.schema")

    # enforce unique field.name within schema
    seen = set()
    for f in cschema:
        if not isinstance(f, dict):
            _log(400, "collection.schema items must be objects", query=q)
            return _err("VALIDATION_ERROR", "collection.schema items must be objects", field="collection.schema")
        fn = f.get("name")
        if not isinstance(fn, str) or not fn:
            _log(400, "schema field missing name", query=q)
            return _err("VALIDATION_ERROR", "schema field missing name", field="collection.schema.name")
        if fn in seen:
            _log(409, f"Duplicate field name in schema: {fn}", query=q)
            return _err("CONFLICT", f"Duplicate field name in schema: {fn}", field=fn, rule="unique field.name within collection schema")
        seen.add(fn)

    # collection name uniqueness vs existing pb_collections
    cols = _load("pb_collections.json")
    if any(isinstance(c, dict) and c.get("name") == cname.strip() and c.get("status") != "deleted" for c in cols):
        _log(409, "Collection name already exists", query=q)
        return _err("CONFLICT", "Collection name already exists", field="collection.name", rule="unique(name)")

    migrations = _load("pb_migrations.json")

    # Determine active migrations_dir: choose most common existing dir, fallback to first row, else default.
    dirs = [m.get("migrations_dir") for m in migrations if isinstance(m, dict) and isinstance(m.get("migrations_dir"), str) and m.get("migrations_dir")]
    migrations_dir = None
    if dirs:
        counts = {}
        for d in dirs:
            counts[d] = counts.get(d, 0) + 1
        migrations_dir = sorted(counts.items(), key=lambda x: (-x[1], x[0]))[0][0]
    else:
        migrations_dir = "/var/lib/pocketbase/migrations"

    ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
    slug = _slugify(name)
    filename = f"{ts}_{slug}.js"

    # unique(migrations_dir, filename)
    existing = {m.get("filename") for m in migrations if isinstance(m, dict) and m.get("migrations_dir") == migrations_dir}
    if filename in existing:
        # add suffix until unique
        i = 1
        while True:
            candidate = f"{ts}_{slug}_{i}.js"
            if candidate not in existing:
                filename = candidate
                break
            i += 1

    now = _now_iso()
    mid = _gen_id("pbm")
    row = {
        "id": mid,
        "migrations_dir": migrations_dir,
        "filename": filename,
        "name": name.strip(),
        "kind": "create_collection",
        "target_collection_id": None,
        "target_collection_name": cname.strip(),
        "payload": {
            "collection": {
                "name": cname.strip(),
                "type": ctype,
                "system": bool(collection.get("system")) if "system" in collection else False,
                "schema": cschema,
                "indexes": collection.get("indexes") if isinstance(collection.get("indexes"), list) else None,
                "list_rule": collection.get("list_rule"),
                "view_rule": collection.get("view_rule"),
                "create_rule": collection.get("create_rule"),
                "update_rule": collection.get("update_rule"),
                "delete_rule": collection.get("delete_rule"),
                "options": collection.get("options") if isinstance(collection.get("options"), dict) else None,
            }
        },
        "up_sql_or_code": None,
        "down_sql_or_code": None,
        "status": "draft",
        "applied_at": None,
        "reverted_at": None,
        "last_error": None,
        "created_at": now,
        "updated_at": now,
    }
    migrations.append(row)
    _save("pb_migrations.json", migrations)

    _log(200, None, query=q, migration_id=mid)
    return row

def add_field_migration(name, field, collection_id=None, collection_name=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _slugify(s):
        s = (s or "").strip().lower()
        s = re.sub(r"[^a-z0-9]+", "_", s)
        s = re.sub(r"_+", "_", s).strip("_")
        return s or "migration"

    def _log(status_code, error=None, query=None, collection_id_for_log=None, migration_id=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "POST",
                "path": "/api/migrations/add-field",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id_for_log,
                "record_id": migration_id,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"name": name, "collection_id": collection_id, "collection_name": collection_name}

    if not isinstance(name, str) or not name.strip():
        _log(400, "name is required", query=q)
        return _err("VALIDATION_ERROR", "name is required", field="name")
    if not isinstance(field, dict):
        _log(400, "field must be an object", query=q)
        return _err("VALIDATION_ERROR", "field must be an object", field="field")

    if collection_id is None and collection_name is None:
        _log(400, "Either collection_id or collection_name must be provided", query=q)
        return _err("VALIDATION_ERROR", "Either collection_id or collection_name must be provided")

    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^pbc_[0-9A-HJKMNP-TV-Z]{17,}$", collection_id.strip()):
            _log(400, "collection_id is malformed", query=q)
            return _err("VALIDATION_ERROR", "collection_id is malformed", field="collection_id")

    if collection_name is not None and (not isinstance(collection_name, str) or not collection_name.strip()):
        _log(400, "collection_name must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "collection_name must be a non-empty string", field="collection_name")

    cols = _load("pb_collections.json")
    target = None
    if collection_id is not None:
        cid = collection_id.strip()
        target = next((c for c in cols if isinstance(c, dict) and c.get("id") == cid and c.get("status") != "deleted"), None)
    if target is None and collection_name is not None:
        cn = collection_name.strip()
        target = next((c for c in cols if isinstance(c, dict) and c.get("name") == cn and c.get("status") != "deleted"), None)
    if target is None:
        _log(404, "Target collection not found", query=q)
        return _err("NOT_FOUND", "Target collection not found")

    fname = field.get("name")
    if not isinstance(fname, str) or not fname.strip():
        _log(400, "field.name is required", query=q, collection_id_for_log=target.get("id"))
        return _err("VALIDATION_ERROR", "field.name is required", field="field.name")

    # Prevent duplicate field names at creation time by checking current schema
    schema = target.get("schema") if isinstance(target.get("schema"), list) else []
    if any(isinstance(f, dict) and f.get("name") == fname.strip() for f in schema):
        _log(409, f"Field already exists: {fname.strip()}", query=q, collection_id_for_log=target.get("id"))
        return _err("CONFLICT", f"Field already exists: {fname.strip()}", field="field.name", rule="unique field.name within collection schema")

    migrations = _load("pb_migrations.json")

    dirs = [m.get("migrations_dir") for m in migrations if isinstance(m, dict) and isinstance(m.get("migrations_dir"), str) and m.get("migrations_dir")]
    migrations_dir = None
    if dirs:
        counts = {}
        for d in dirs:
            counts[d] = counts.get(d, 0) + 1
        migrations_dir = sorted(counts.items(), key=lambda x: (-x[1], x[0]))[0][0]
    else:
        migrations_dir = "/var/lib/pocketbase/migrations"

    ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
    slug = _slugify(name)
    filename = f"{ts}_{slug}.js"
    existing = {m.get("filename") for m in migrations if isinstance(m, dict) and m.get("migrations_dir") == migrations_dir}
    if filename in existing:
        i = 1
        while True:
            cand = f"{ts}_{slug}_{i}.js"
            if cand not in existing:
                filename = cand
                break
            i += 1

    now = _now_iso()
    mid = _gen_id("pbm")
    row = {
        "id": mid,
        "migrations_dir": migrations_dir,
        "filename": filename,
        "name": name.strip(),
        "kind": "add_field",
        "target_collection_id": target.get("id"),
        "target_collection_name": target.get("name"),
        "payload": {"field": field},
        "up_sql_or_code": None,
        "down_sql_or_code": None,
        "status": "draft",
        "applied_at": None,
        "reverted_at": None,
        "last_error": None,
        "created_at": now,
        "updated_at": now,
    }
    migrations.append(row)
    _save("pb_migrations.json", migrations)

    _log(200, None, query=q, collection_id_for_log=target.get("id"), migration_id=mid)
    return row

def list_migrations(status=None, kind=None, target_collection_id=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, math, statistics, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # Generate ULID-like sortable id; not a strict ULID but matches allowed charset and length.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        # 10 chars time part base32-ish
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        # 16 chars random part
        import secrets
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return prefix + "_" + "".join(out)

    def _log(status_code, path, method="GET", query=None, collection_id=None, record_id=None, error=None, started=None):
        logs = _load("pb_api_logs.json")
        if started is None:
            started = time.time()
        duration_ms = int(max(0, min(3600000, round((time.time() - started) * 1000))))
        ts = _now()
        row = {
            "id": _gen_id("pbl"),
            "request_id": None,
            "method": method,
            "path": path,
            "query": query if isinstance(query, dict) or query is None else None,
            "status_code": int(status_code),
            "duration_ms": duration_ms,
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": collection_id,
            "record_id": record_id,
            "error": error,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("pb_api_logs.json", logs)

    started = time.time()
    path = "/migrations"

    # Validate inputs
    valid_status = {"draft", "applied", "reverted", "failed"}
    valid_kind = {"empty", "create_collection", "add_field", "custom"}

    if status is not None and (not isinstance(status, str) or status not in valid_status):
        _log(400, path, "GET", query={"status": status}, error="Invalid status", started=started)
        return _err("VALIDATION_ERROR", "Invalid status", field="status")

    if kind is not None and (not isinstance(kind, str) or kind not in valid_kind):
        _log(400, path, "GET", query={"kind": kind}, error="Invalid kind", started=started)
        return _err("VALIDATION_ERROR", "Invalid kind", field="kind")

    if target_collection_id is not None:
        if not isinstance(target_collection_id, str):
            _log(400, path, "GET", query={"target_collection_id": target_collection_id}, error="Invalid target_collection_id", started=started)
            return _err("VALIDATION_ERROR", "Invalid target_collection_id", field="target_collection_id")
        if not re.match(r"^pbc_[0-9A-HJKMNP-TV-Z]{17,}$", target_collection_id):
            _log(400, path, "GET", query={"target_collection_id": target_collection_id}, error="Malformed target_collection_id", started=started)
            return _err("VALIDATION_ERROR", "Malformed target_collection_id", field="target_collection_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, path, "GET", query={"limit": limit}, error="Invalid limit", started=started)
        return _err("VALIDATION_ERROR", "Invalid limit", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log(400, path, "GET", query={"cursor": cursor}, error="Invalid cursor", started=started)
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    if sort is None:
        sort = "filename"
    if not isinstance(sort, str) or sort.strip() == "":
        _log(400, path, "GET", query={"sort": sort}, error="Invalid sort", started=started)
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")

    # Load and determine active migrations_dir (use latest updated migration row's dir; else default).
    migrations = _load("pb_migrations.json")
    active_dir = None
    if migrations:
        def _dt(v):
            if not isinstance(v, str):
                return ""
            return v
        last = max(migrations, key=lambda r: (_dt(r.get("updated_at")) or _dt(r.get("created_at")) or "", r.get("id") or ""))
        active_dir = last.get("migrations_dir")
    if not isinstance(active_dir, str) or active_dir.strip() == "":
        active_dir = "migrations"

    # Filter to active dir
    rows = [r for r in migrations if r.get("migrations_dir") == active_dir]

    # Apply filters
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if kind is not None:
        rows = [r for r in rows if r.get("kind") == kind]
    if target_collection_id is not None:
        rows = [r for r in rows if r.get("target_collection_id") == target_collection_id]

    # Sorting
    desc = False
    key = sort
    if sort.startswith("-"):
        desc = True
        key = sort[1:]
    allowed_sort = {"created_at", "updated_at", "filename", "name", "status", "kind"}
    if key not in allowed_sort:
        _log(400, path, "GET", query={"sort": sort}, error="Unsupported sort field", started=started)
        return _err("VALIDATION_ERROR", "Unsupported sort field", field="sort", allowed=sorted(list(allowed_sort)))

    def _sort_key(r):
        v = r.get(key)
        # Ensure stable ordering and consistent types
        if v is None:
            v = ""
        return (str(v), str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=desc)

    # Cursor handling (opaque)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            decoded = raw.decode("utf-8")
            if decoded.startswith("off:"):
                offset = int(decoded.split(":", 1)[1])
            else:
                raise ValueError("bad cursor")
            if offset < 0:
                raise ValueError("bad cursor")
        except Exception:
            _log(400, path, "GET", query={"cursor": cursor}, error="Malformed cursor", started=started)
            return _err("VALIDATION_ERROR", "Malformed cursor", field="cursor")

    total = len(rows)
    page_rows = rows[offset: offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        nxt = f"off:{offset + limit}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(nxt).decode("utf-8").rstrip("=")

    _log(200, path, "GET", query={"status": status, "kind": kind, "target_collection_id": target_collection_id, "limit": limit, "cursor": cursor, "sort": sort, "migrations_dir": active_dir}, started=started)
    return {
        "migrations_dir": active_dir,
        "items": page_rows,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
    }

def apply_migration(migration_id=None, filename=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, query=None, migration_id_for_log=None, collection_id=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "POST",
                "path": "/api/migrations/apply",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id,
                "record_id": migration_id_for_log,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"migration_id": migration_id, "filename": filename}

    if migration_id is None and filename is None:
        _log(400, "Either migration_id or filename must be provided", query=q)
        return _err("VALIDATION_ERROR", "Either migration_id or filename must be provided")

    if migration_id is not None and (not isinstance(migration_id, str) or not re.match(r"^pbm_[0-9A-HJKMNP-TV-Z]{17,}$", migration_id.strip())):
        _log(400, "migration_id is malformed", query=q)
        return _err("VALIDATION_ERROR", "migration_id is malformed", field="migration_id")
    if filename is not None and (not isinstance(filename, str) or not filename.strip()):
        _log(400, "filename must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "filename must be a non-empty string", field="filename")

    migrations = _load("pb_migrations.json")
    m = None
    if migration_id is not None:
        mid = migration_id.strip()
        m = next((x for x in migrations if isinstance(x, dict) and x.get("id") == mid), None)
    if m is None and filename is not None:
        fn = filename.strip()
        m = next((x for x in migrations if isinstance(x, dict) and x.get("filename") == fn), None)

    if not m:
        _log(404, "Migration not found", query=q)
        return _err("NOT_FOUND", "Migration not found")

    if m.get("status") not in ("draft", "reverted"):
        _log(409, "Migration is not in an applicable state", query=q, migration_id_for_log=m.get("id"), collection_id=m.get("target_collection_id"))
        return _err("CONFLICT", "Migration is not in an applicable state", rule="apply_migration allowed only from draft or reverted")

    # Enforce: cannot apply if any earlier migration in same dir is still in 'draft'
    mdir = m.get("migrations_dir")
    if isinstance(mdir, str) and mdir:
        same_dir = [x for x in migrations if isinstance(x, dict) and x.get("migrations_dir") == mdir]
        same_dir_sorted = sorted(same_dir, key=lambda x: (str(x.get("filename") or ""), str(x.get("id") or "")))
        before = [x for x in same_dir_sorted if str(x.get("filename") or "") < str(m.get("filename") or "")]
        pending_before = [x for x in before if x.get("status") == "draft"]
        if pending_before:
            _log(409, "Earlier pending draft migration exists", query=q, migration_id_for_log=m.get("id"), collection_id=m.get("target_collection_id"))
            return _err("CONFLICT", "Earlier pending draft migration exists", rule="cannot apply when earlier migration is still in 'draft'")

    now = _now_iso()

    def _fail(reason):
        # Transition to failed
        m["status"] = "failed"
        m["last_error"] = str(reason)
        m["updated_at"] = now
        _save("pb_migrations.json", migrations)
        _log(500, str(reason), query=q, migration_id_for_log=m.get("id"), collection_id=m.get("target_collection_id"))
        return _err("CONFLICT", "Migration apply failed", last_error=str(reason))

    kind = m.get("kind")
    try:
        if kind == "create_collection":
            payload = m.get("payload") if isinstance(m.get("payload"), dict) else {}
            cdef = payload.get("collection") if isinstance(payload.get("collection"), dict) else None
            if not cdef:
                return _fail("Missing payload.collection")
            cols = _load("pb_collections.json")
            cname = cdef.get("name")
            ctype = cdef.get("type")
            cschema = cdef.get("schema")
            if not isinstance(cname, str) or not cname.strip():
                return _fail("Invalid collection name")
            if ctype not in ("base", "auth", "view"):
                return _fail("Invalid collection type")
            if not isinstance(cschema, list):
                return _fail("Invalid collection schema")
            if any(isinstance(c, dict) and c.get("name") == cname.strip() and c.get("status") != "deleted" for c in cols):
                return _fail("Collection name already exists")
            cid = _gen_id("pbc")
            new_col = {
                "id": cid,
                "name": cname.strip(),
                "type": ctype,
                "system": bool(cdef.get("system")) if "system" in cdef else False,
                "schema": cschema,
                "indexes": cdef.get("indexes") if isinstance(cdef.get("indexes"), list) else None,
                "list_rule": cdef.get("list_rule"),
                "view_rule": cdef.get("view_rule"),
                "create_rule": cdef.get("create_rule"),
                "update_rule": cdef.get("update_rule"),
                "delete_rule": cdef.get("delete_rule"),
                "options": cdef.get("options") if isinstance(cdef.get("options"), dict) else None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            cols.append(new_col)
            _save("pb_collections.json", cols)
            m["target_collection_id"] = cid
            m["target_collection_name"] = cname.strip()

        elif kind == "add_field":
            payload = m.get("payload") if isinstance(m.get("payload"), dict) else {}
            fdef = payload.get("field") if isinstance(payload.get("field"), dict) else None
            if not fdef:
                return _fail("Missing payload.field")
            cid = m.get("target_collection_id")
            if not isinstance(cid, str) or not cid:
                return _fail("Missing target_collection_id")
            cols = _load("pb_collections.json")
            col = next((c for c in cols if isinstance(c, dict) and c.get("id") == cid and c.get("status") != "deleted"), None)
            if not col:
                return _fail("Target collection not found")
            schema = col.get("schema") if isinstance(col.get("schema"), list) else []
            fname = fdef.get("name")
            if not isinstance(fname, str) or not fname.strip():
                return _fail("Invalid field.name")
            if any(isinstance(f, dict) and f.get("name") == fname.strip() for f in schema):
                return _fail("Field already exists")
            schema.append(fdef)
            col["schema"] = schema
            col["updated_at"] = now
            _save("pb_collections.json", cols)

        elif kind in ("empty", "custom"):
            # nothing to apply in this simplified backend
            pass
        else:
            return _fail(f"Unknown migration kind: {kind}")

    except Exception as e:
        return _fail(e)

    # Success transition
    m["status"] = "applied"
    m["applied_at"] = now
    m["last_error"] = None
    m["updated_at"] = now
    _save("pb_migrations.json", migrations)
    _log(200, None, query=q, migration_id_for_log=m.get("id"), collection_id=m.get("target_collection_id"))
    return m

