                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id,
                "record_id": migration_id_for_log,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"migration_id": migration_id, "filename": filename}

    if migration_id is None and filename is None:
        _log(400, "Either migration_id or filename must be provided", query=q)
        return _err("VALIDATION_ERROR", "Either migration_id or filename must be provided")

    if migration_id is not None and (not isinstance(migration_id, str) or not re.match(r"^pbm_[0-9A-HJKMNP-TV-Z]{17,}$", migration_id.strip())):
        _log(400, "migration_id is malformed", query=q)
        return _err("VALIDATION_ERROR", "migration_id is malformed", field="migration_id")
    if filename is not None and (not isinstance(filename, str) or not filename.strip()):
        _log(400, "filename must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "filename must be a non-empty string", field="filename")

    migrations = _load("pb_migrations.json")
    m = None
    if migration_id is not None:
        mid = migration_id.strip()
        m = next((x for x in migrations if isinstance(x, dict) and x.get("id") == mid), None)
    if m is None and filename is not None:
        fn = filename.strip()
        m = next((x for x in migrations if isinstance(x, dict) and x.get("filename") == fn), None)

    if not m:
        _log(404, "Migration not found", query=q)
        return _err("NOT_FOUND", "Migration not found")

    if m.get("status") != "applied":
        _log(409, "Migration is not applied", query=q, migration_id_for_log=m.get("id"), collection_id=m.get("target_collection_id"))
        return _err("CONFLICT", "Migration is not applied", rule="revert_migration allowed only from applied")

    now = _now_iso()

    # Simplified revert: we do not drop created collections or remove fields (no down steps stored)
    # but still enforce lifecycle transition and audit timestamps.
    m["status"] = "reverted"
    m["reverted_at"] = now
    m["updated_at"] = now
    m["last_error"] = None
    _save("pb_migrations.json", migrations)

    _log(200, None, query=q, migration_id_for_log=m.get("id"), collection_id=m.get("target_collection_id"))
    return m

def apply_all_migrations(limit=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        import secrets
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return prefix + "_" + "".join(out)

    def _log(status_code, path, method="POST", query=None, collection_id=None, record_id=None, error=None, started=None):
        logs = _load("pb_api_logs.json")
        if started is None:
            started = time.time()
        duration_ms = int(max(0, min(3600000, round((time.time() - started) * 1000))))
        ts = _now()
        row = {
            "id": _gen_id("pbl"),
            "request_id": None,
            "method": method,
            "path": path,
            "query": query if isinstance(query, dict) or query is None else None,
            "status_code": int(status_code),
            "duration_ms": duration_ms,
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": collection_id,
            "record_id": record_id,
            "error": error,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("pb_api_logs.json", logs)

    started = time.time()
    path = "/migrations/applyAll"

    if limit is None:
        limit = 1000  # server default when omitted for this tool
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log(400, path, "POST", query={"limit": limit}, error="Invalid limit", started=started)
        return _err("VALIDATION_ERROR", "Invalid limit", field="limit")

    migrations = _load("pb_migrations.json")
    collections = _load("pb_collections.json")
    records = _load("pb_records.json")

    # Determine active migrations_dir (latest updated row), apply only within it.
    active_dir = None
    if migrations:
        last = max(migrations, key=lambda r: (str(r.get("updated_at") or r.get("created_at") or ""), str(r.get("id") or "")))
        active_dir = last.get("migrations_dir")
    if not isinstance(active_dir, str) or active_dir.strip() == "":
        active_dir = "migrations"

    # helper apply logic for a single migration row (mutates in-memory lists)
    def _unique_collection_name(name, exclude_id=None):
        for c in collections:
            if c.get("name") == name and c.get("id") != exclude_id and c.get("status") != "deleted":
                return False
        return True

    def _validate_field_objects_unique(schema_arr):
        if not isinstance(schema_arr, list):
            return False, "schema must be an array"
        seen = set()
        for f in schema_arr:
            if not isinstance(f, dict):
                return False, "schema must contain objects"
            n = f.get("name")
            if not isinstance(n, str) or n.strip() == "":
                return False, "field.name must be a non-empty string"
            if n in seen:
                return False, "field.name must be unique within the collection"
            seen.add(n)
        return True, None

    def _find_collection_by_id(cid):
        for c in collections:
            if c.get("id") == cid:
                return c
        return None

    # order by filename asc
    pending = [m for m in migrations if m.get("migrations_dir") == active_dir and m.get("status") in ("draft", "reverted") and isinstance(m.get("filename"), str)]
    pending.sort(key=lambda r: (r.get("filename"), r.get("id") or ""))

    # Ordering/consistency: cannot apply if any earlier migration is still draft and later is reverted etc.
    # We'll enforce per apply: if there exists any draft earlier than current, it's conflict.
    applied = []
    failed = None
    ts = _now()

    for m in pending[:limit]:
        # ensure earlier draft none
        earlier_draft = any(
            (x.get("migrations_dir") == active_dir and isinstance(x.get("filename"), str) and x.get("filename") < m.get("filename") and x.get("status") == "draft")
            for x in migrations
        )
        if earlier_draft:
            failed = {"id": m.get("id"), "filename": m.get("filename"), "error": "Earlier draft migrations exist"}
            break

        kind = m.get("kind")
        ok = True
        err = None
        try:
            if kind == "create_collection":
                payload = m.get("payload")
                if not isinstance(payload, dict):
                    ok = False
                    err = "Missing payload for create_collection"
                else:
                    name = payload.get("name") or m.get("target_collection_name")
                    ctype = payload.get("type") or "base"
                    schema_arr = payload.get("schema") if "schema" in payload else payload.get("fields")
                    if not isinstance(name, str) or name.strip() == "":
                        ok = False
                        err = "Collection name is required"
                    elif ctype not in ("base", "auth", "view"):
                        ok = False
                        err = "Invalid collection type"
                    elif ctype == "view":
                        ok = False
                        err = "Cannot create view collections via migration apply in this server"
                    elif not _unique_collection_name(name):
                        ok = False
                        err = "Collection name already exists"
                    else:
                        if schema_arr is None:
                            schema_arr = []
                        valid, msg = _validate_field_objects_unique(schema_arr)
                        if not valid:
                            ok = False
                            err = msg
                        else:
                            new_id = payload.get("id")
                            if new_id is None or not isinstance(new_id, str) or not re.match(r"^pbc_[0-9A-HJKMNP-TV-Z]{17,}$", new_id):
                                new_id = _gen_id("pbc")
                            collections.append({
                                "id": new_id,
                                "name": name,
                                "type": ctype,
                                "system": bool(payload.get("system", False)),
                                "schema": schema_arr,
                                "indexes": payload.get("indexes"),
                                "list_rule": payload.get("list_rule"),
                                "view_rule": payload.get("view_rule"),
                                "create_rule": payload.get("create_rule"),
                                "update_rule": payload.get("update_rule"),
                                "delete_rule": payload.get("delete_rule"),
                                "options": payload.get("options"),
                                "status": "active",
                                "created_at": ts,
                                "updated_at": ts,
                            })
                            m["target_collection_id"] = new_id
                            m["target_collection_name"] = name

            elif kind == "add_field":
                cid = m.get("target_collection_id")
                if not isinstance(cid, str) or not re.match(r"^pbc_[0-9A-HJKMNP-TV-Z]{17,}$", cid):
                    ok = False
                    err = "Missing/invalid target_collection_id"
                else:
                    col = _find_collection_by_id(cid)
                    if col is None or col.get("status") == "deleted":
                        ok = False
                        err = "Target collection not found"
                    elif col.get("status") != "active":
                        ok = False
                        err = "Target collection is not active"
                    else:
                        payload = m.get("payload")
                        if not isinstance(payload, dict) or not isinstance(payload.get("field"), dict):
                            field_def = payload if isinstance(payload, dict) else None
                        else:
                            field_def = payload.get("field")
                        if not isinstance(field_def, dict):
                            ok = False
                            err = "Missing field definition in payload"
                        else:
                            fname = field_def.get("name")
                            if not isinstance(fname, str) or fname.strip() == "":
                                ok = False
                                err = "Field name is required"
                            else:
                                schema_arr = col.get("schema")
                                if not isinstance(schema_arr, list):
                                    schema_arr = []
                                if any(isinstance(f, dict) and f.get("name") == fname for f in schema_arr):
                                    ok = False
                                    err = "Field name already exists in collection schema"
                                else:
                                    schema_arr.append(field_def)
                                    col["schema"] = schema_arr
                                    col["updated_at"] = ts

            elif kind in ("empty", "custom"):
                pass
            else:
                ok = False
                err = "Unknown migration kind"
        except Exception as e:
            ok = False
            err = f"Internal error while applying migration: {e}"

        if ok:
            m["status"] = "applied"
            m["applied_at"] = ts
            m["last_error"] = None
            m["updated_at"] = ts
            applied.append({"id": m.get("id"), "filename": m.get("filename"), "kind": m.get("kind"), "target_collection_id": m.get("target_collection_id")})
        else:
            m["status"] = "failed"
            m["last_error"] = err or "Apply failed"
            m["updated_at"] = ts
            failed = {"id": m.get("id"), "filename": m.get("filename"), "error": m.get("last_error")}
            break

    # persist mutated state
    _save("pb_collections.json", collections)
    _save("pb_records.json", records)
    _save("pb_migrations.json", migrations)

    if failed:
        _log(409, path, "POST", query={"limit": limit, "migrations_dir": active_dir}, error=failed.get("error"), started=started)
        return _err("CONFLICT", "Failed to apply all migrations", migrations_dir=active_dir, applied=applied, failure=failed)

    _log(200, path, "POST", query={"limit": limit, "migrations_dir": active_dir}, started=started)
    return {
        "migrations_dir": active_dir,
        "applied": applied,
        "applied_count": len(applied),
        "limit": limit,
        "stopped_on_failure": False,
    }

def revert_to_migration(target_migration_id, migrations_dir=None, dry_run=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, query=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "POST",
                "path": "/api/migrations/revert-to",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": None,
                "record_id": None,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"target_migration_id": target_migration_id, "migrations_dir": migrations_dir, "dry_run": dry_run}

    if not isinstance(target_migration_id, str) or not re.match(r"^pbm_[0-9A-HJKMNP-TV-Z]{18,}$", target_migration_id.strip()):
        _log(400, "target_migration_id is malformed", query=q)
        return _err("VALIDATION_ERROR", "target_migration_id is malformed", field="target_migration_id")

    if dry_run is None:
        dry_run = False
    if not isinstance(dry_run, bool):
        _log(400, "dry_run must be boolean", query=q)
        return _err("VALIDATION_ERROR", "dry_run must be boolean", field="dry_run")

    migrations = _load("pb_migrations.json")
    tgt = next((m for m in migrations if isinstance(m, dict) and m.get("id") == target_migration_id.strip()), None)
    if not tgt:
        _log(404, "Target migration not found", query=q)
        return _err("NOT_FOUND", "Target migration not found")

    mdir = tgt.get("migrations_dir")
    if migrations_dir is not None:
        if not isinstance(migrations_dir, str) or not migrations_dir.strip():
            _log(400, "migrations_dir must be a non-empty string", query=q)
            return _err("VALIDATION_ERROR", "migrations_dir must be a non-empty string", field="migrations_dir")
        if migrations_dir.strip() != mdir:
            _log(400, "migrations_dir does not match target migration directory", query=q)
            return _err("VALIDATION_ERROR", "migrations_dir does not match target migration directory", field="migrations_dir")

    same_dir = [m for m in migrations if isinstance(m, dict) and m.get("migrations_dir") == mdir]
    same_dir_sorted = sorted(same_dir, key=lambda x: (str(x.get("filename") or ""), str(x.get("id") or "")))
    tgt_fn = str(tgt.get("filename") or "")

    # revert all applied migrations with filename > target.filename, in reverse order
    to_revert = [m for m in same_dir_sorted if m.get("status") == "applied" and str(m.get("filename") or "") > tgt_fn]
    plan = list(reversed(to_revert))

    results = []
    now = _now_iso()
    if dry_run:
        for m in plan:
            results.append({"migration_id": m.get("id"), "filename": m.get("filename"), "action": "revert", "status": "planned"})
        _log(200, None, query=q)
        return {"dry_run": True, "migrations_dir": mdir, "target": {"id": tgt.get("id"), "filename": tgt.get("filename")}, "plan": results}

    # execute
    for m in plan:
        if m.get("status") != "applied":
            results.append({"migration_id": m.get("id"), "filename": m.get("filename"), "action": "revert", "status": "skipped", "reason": "not applied"})
            continue
        m["status"] = "reverted"
        m["reverted_at"] = now
        m["updated_at"] = now
        m["last_error"] = None
        results.append({"migration_id": m.get("id"), "filename": m.get("filename"), "action": "revert", "status": "ok"})

    _save("pb_migrations.json", migrations)
    _log(200, None, query=q)
    return {"dry_run": False, "migrations_dir": mdir, "target": {"id": tgt.get("id"), "filename": tgt.get("filename")}, "plan": results}

def list_logs(filter=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32]); ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, query=None):
        logs = _load("pb_api_logs.json")
        logs.append({
            "id": _gen_id("pbl"),
            "request_id": None,
            "method": "GET",
            "path": "/api/logs/list",
            "query": query if isinstance(query, dict) else None,
            "status_code": int(status_code),
            "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": None,
            "record_id": None,
            "error": error,
            "created_at": _now,
            "updated_at": _now,
        })
        _save("pb_api_logs.json", logs)

    # Validate inputs
    if filter is not None and not isinstance(filter, dict):
        _log(400, "filter must be an object", query={"filter": str(filter)})
        return _err("VALIDATION_ERROR", "filter must be an object")
    if sort is not None and not isinstance(sort, str):
        _log(400, "sort must be a string")
        return _err("VALIDATION_ERROR", "sort must be a string")
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, "limit out of bounds", query={"limit": limit})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Cursor is opaque; accept any string. If it can be decoded, use it, else treat as start=0.
    start = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8", "ignore")
            if decoded.startswith("offset:"):
                start = int(decoded.split(":", 1)[1])
        except Exception:
            start = 0

    logs = _load("pb_api_logs.json")
    rows = [r for r in logs if isinstance(r, dict)]

    f = filter or {}
    allowed_keys = {
        "request_id", "method", "path", "status_code", "status_code_min", "status_code_max",
        "duration_ms_min", "duration_ms_max", "ip", "user_agent", "auth_record_id",
        "collection_id", "record_id", "has_error", "created_at_from", "created_at_to"
    }
    for k in f.keys():
        if k not in allowed_keys:
            _log(400, f"Unknown filter key: {k}", query={"filter": f})
            return _err("VALIDATION_ERROR", f"Unknown filter key: {k}")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    created_from = _parse_dt(f.get("created_at_from"))
    if f.get("created_at_from") is not None and created_from is None:
        _log(400, "created_at_from must be ISO datetime", query={"filter": f})
        return _err("VALIDATION_ERROR", "created_at_from must be an ISO datetime")
    created_to = _parse_dt(f.get("created_at_to"))
    if f.get("created_at_to") is not None and created_to is None:
        _log(400, "created_at_to must be ISO datetime", query={"filter": f})
        return _err("VALIDATION_ERROR", "created_at_to must be an ISO datetime")

    if "method" in f and f["method"] is not None:
        if f["method"] not in ("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "HEAD"):
            _log(400, "Invalid method filter", query={"filter": f})
            return _err("VALIDATION_ERROR", "Invalid method enum")

    def _match(r):
        if f.get("request_id") is not None and r.get("request_id") != f.get("request_id"):
            return False
        if f.get("method") is not None and r.get("method") != f.get("method"):
            return False
        if f.get("path") is not None and r.get("path") != f.get("path"):
            return False
        if f.get("status_code") is not None and r.get("status_code") != f.get("status_code"):
            return False
        if f.get("status_code_min") is not None and isinstance(r.get("status_code"), int) and r.get("status_code") < f.get("status_code_min"):
            return False
        if f.get("status_code_max") is not None and isinstance(r.get("status_code"), int) and r.get("status_code") > f.get("status_code_max"):
            return False
        if f.get("duration_ms_min") is not None and isinstance(r.get("duration_ms"), int) and r.get("duration_ms") < f.get("duration_ms_min"):
            return False
        if f.get("duration_ms_max") is not None and isinstance(r.get("duration_ms"), int) and r.get("duration_ms") > f.get("duration_ms_max"):
            return False
        if f.get("ip") is not None and r.get("ip") != f.get("ip"):
            return False
        if f.get("user_agent") is not None and r.get("user_agent") != f.get("user_agent"):
            return False
        if f.get("auth_record_id") is not None and r.get("auth_record_id") != f.get("auth_record_id"):
            return False
        if f.get("collection_id") is not None and r.get("collection_id") != f.get("collection_id"):
            return False
        if f.get("record_id") is not None and r.get("record_id") != f.get("record_id"):
            return False
        if f.get("has_error") is True and not (isinstance(r.get("error"), str) and r.get("error")):
            return False
        if f.get("has_error") is False and (isinstance(r.get("error"), str) and r.get("error")):
            return False
        if created_from is not None:
            rd = _parse_dt(r.get("created_at"))
            if rd is None or rd < created_from:
                return False
        if created_to is not None:
            rd = _parse_dt(r.get("created_at"))
            if rd is None or rd > created_to:
                return False
        return True

    rows = [r for r in rows if _match(r)]

    # sort: e.g. "-updated_at" or "duration_ms"
    key = "created_at"
    desc = True
    if isinstance(sort, str) and sort.strip():
        s = sort.strip()
        if s.startswith("-"):
            desc = True
            key = s[1:]
        else:
            desc = False
            key = s
    def _sort_key(r):
        v = r.get(key)
        return (v is None, v)
    rows.sort(key=_sort_key, reverse=desc)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = base64.urlsafe_b64encode(f"offset:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200, None, query={"filter": f, "sort": sort, "limit": limit, "cursor": cursor})
    return {"logs": page, "total": total, "has_more": next_cursor is not None, "next_cursor": next_cursor}

