def get_logs_stats(filter=None, group_by=None, **_extra):
    import json, os, datetime, re, time, hashlib, math

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _new_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        ts = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[ts % 32])
            ts //= 32
        ts_part = "".join(reversed(chars))
        rnd = hashlib.sha256(f"{time.time_ns()}:{os.getpid()}:{os.urandom(8)}".encode("utf-8")).digest()
        r = int.from_bytes(rnd[:10], "big")
        rand_chars = []
        for _ in range(16):
            rand_chars.append(alphabet[r % 32])
            r //= 32
        return f"{prefix}_{ts_part}{''.join(rand_chars)}"

    def _log(status_code, path, method="GET", query=None, error=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        entry = {
            "id": _new_ulid("pbl"),
            "request_id": None,
            "method": method,
            "path": path,
            "query": query if isinstance(query, dict) else None,
            "status_code": int(status_code),
            "duration_ms": int(max(0, round((time.time() - _t0) * 1000))),
            "ip": None,
            "user_agent": None,
            "auth_record_id": None,
            "collection_id": None,
            "record_id": None,
            "error": error,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(entry)
        _save("pb_api_logs.json", logs)

    # Validate
    if filter is not None and not isinstance(filter, dict):
        _log(400, "/logs/stats", query={"filter": filter, "group_by": group_by}, error="Invalid filter")
        return _err("VALIDATION_ERROR", "filter must be an object")

    f = filter or {}
    allowed_filter_keys = {"method", "path", "status_code", "auth_record_id", "collection_id", "record_id", "created_at_from", "created_at_to"}
    unknown = [k for k in f.keys() if k not in allowed_filter_keys]
    if unknown:
        _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Unknown filter keys")
        return _err("VALIDATION_ERROR", "Unknown filter keys", unknown_keys=unknown)

    methods = {"GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "HEAD"}
    if "method" in f and f["method"] is not None:
        if not isinstance(f["method"], str) or f["method"] not in methods:
            _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Invalid method")
            return _err("VALIDATION_ERROR", "Invalid method enum")

    if "collection_id" in f and f["collection_id"] is not None:
        if not isinstance(f["collection_id"], str) or not re.match(r"^pbc_[0-9A-HJKMNP-TV-Z]{18,}$", f["collection_id"]):
            _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Invalid collection_id")
            return _err("VALIDATION_ERROR", "collection_id must be a pbc_ ULID")

    if "status_code" in f and f["status_code"] is not None and not isinstance(f["status_code"], int):
        _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Invalid status_code")
        return _err("VALIDATION_ERROR", "status_code must be an integer")

    dt_from = _parse_iso(f.get("created_at_from"))
    if f.get("created_at_from") is not None and dt_from is None:
        _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Invalid created_at_from")
        return _err("VALIDATION_ERROR", "created_at_from must be an ISO datetime")

    dt_to = _parse_iso(f.get("created_at_to"))
    if f.get("created_at_to") is not None and dt_to is None:
        _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Invalid created_at_to")
        return _err("VALIDATION_ERROR", "created_at_to must be an ISO datetime")

    if dt_from and dt_to and dt_from > dt_to:
        _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Invalid datetime range")
        return _err("VALIDATION_ERROR", "created_at_from must be <= created_at_to")

    if group_by is None:
        group_by = "none"
    if not isinstance(group_by, str) or group_by not in {"method", "path", "status_code", "collection_id", "auth_record_id", "none"}:
        _log(400, "/logs/stats", query={"filter": f, "group_by": group_by}, error="Invalid group_by")
        return _err("VALIDATION_ERROR", "group_by must be one of method, path, status_code, collection_id, auth_record_id, none")

    logs = _load("pb_api_logs.json")
    rows = [r for r in logs if isinstance(r, dict)]

    def _row_dt(row):
        d = _parse_iso(row.get("created_at"))
        if d is None:
            return None
        return d

    def _match(row):
        if f.get("method") is not None and row.get("method") != f.get("method"):
            return False
        if f.get("path") is not None and row.get("path") != f.get("path"):
            return False
        if f.get("status_code") is not None and row.get("status_code") != f.get("status_code"):
            return False
        if f.get("auth_record_id") is not None and row.get("auth_record_id") != f.get("auth_record_id"):
            return False
        if f.get("collection_id") is not None and row.get("collection_id") != f.get("collection_id"):
            return False
        if f.get("record_id") is not None and row.get("record_id") != f.get("record_id"):
            return False
        if dt_from is not None or dt_to is not None:
            dtr = _row_dt(row)
            if dtr is None:
                return False
            if dt_from is not None and dtr < dt_from:
                return False
            if dt_to is not None and dtr > dt_to:
                return False
        return True

    scoped = [r for r in rows if _match(r)]

    def _classify(code):
        if not isinstance(code, int):
            return "other"
        if 200 <= code <= 299:
            return "2xx"
        if 400 <= code <= 499:
            return "4xx"
        if 500 <= code <= 599:
            return "5xx"
        return "other"

    def _p95(values):
        if not values:
            return None
        vs = sorted(values)
        k = int(math.ceil(0.95 * len(vs))) - 1
        k = max(0, min(k, len(vs) - 1))
        return vs[k]

    def _aggregate(items):
        durations = [r.get("duration_ms") for r in items if isinstance(r.get("duration_ms"), int)]
        total = len(items)
        by_class = {"2xx": 0, "4xx": 0, "5xx": 0, "other": 0}
        for r in items:
            by_class[_classify(r.get("status_code"))] += 1
        avg = (sum(durations) / len(durations)) if durations else None
        p95 = _p95(durations)
        return {
            "total_requests": total,
            "status_code_class_counts": {"2xx": by_class["2xx"], "4xx": by_class["4xx"], "5xx": by_class["5xx"]},
            "avg_duration_ms": avg,
            "p95_duration_ms": p95,
        }

    if group_by == "none":
        out = {"group_by": "none", "stats": _aggregate(scoped)}
        _log(200, "/logs/stats", query={"filter": f, "group_by": group_by}, error=None)
        return out

    # Group
    def _gkey(r):
        v = r.get(group_by)
        if v is None:
            return None
        return v

    groups = {}
    for r in scoped:
        k = _gkey(r)
        groups.setdefault(k, []).append(r)

    items = []
    for k, vals in groups.items():
        agg = _aggregate(vals)
        agg["key"] = k
        items.append(agg)

    # stable-ish sort by key stringification
    items = sorted(items, key=lambda x: "" if x.get("key") is None else str(x.get("key")))

    _log(200, "/logs/stats", query={"filter": f, "group_by": group_by}, error=None)
    return {"group_by": group_by, "items": items, "total_groups": len(items), "total_requests": len(scoped)}

