                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id,
                "record_id": record_id,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"collection": collection, "id": id}

    if not isinstance(collection, str) or not collection.strip():
        _log(400, "collection must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "collection must be a non-empty string", field="collection")
    if not isinstance(id, str) or not id.strip():
        _log(400, "id must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    cols = _load("pb_collections.json")
    ckey = collection.strip()
    col = next((c for c in cols if isinstance(c, dict) and c.get("status") != "deleted" and (c.get("id") == ckey or c.get("name") == ckey)), None)
    if not col:
        _log(404, "Collection not found", query=q)
        return _err("NOT_FOUND", "Collection not found")

    if col.get("status") != "active":
        _log(400, "Owning collection is not active", collection_id=col.get("id"), query=q)
        return _err("VALIDATION_ERROR", "Owning collection is not active", rule="pb_collections.status must be 'active'")

    records = _load("pb_records.json")
    rid = id.strip()
    rec = next((r for r in records if isinstance(r, dict) and r.get("collection_id") == col.get("id") and r.get("id") == rid), None)
    if not rec:
        _log(404, "Record not found", collection_id=col.get("id"), record_id=rid, query=q)
        return _err("NOT_FOUND", "Record not found")

    if rec.get("status") == "deleted":
        _log(400, "Record already deleted", collection_id=col.get("id"), record_id=rid, query=q)
        return _err("VALIDATION_ERROR", "Record already deleted", rule="already deleted")

    # transition active -> deleted only
    if rec.get("status") != "active":
        _log(409, "Invalid record status transition", collection_id=col.get("id"), record_id=rid, query=q)
        return _err("INVALID_TRANSITION", "Invalid record status transition")

    now = _now_iso()
    rec["status"] = "deleted"
    rec["updated_at"] = now
    _save("pb_records.json", records)

    out = {
        "id": rec.get("id"),
        "collectionId": rec.get("collection_id"),
        "collectionName": rec.get("collection_name"),
        "created": rec.get("created_at"),
        "updated": rec.get("updated_at"),
        **(rec.get("data") if isinstance(rec.get("data"), dict) else {}),
        "expand": {},
    }
    _log(200, None, collection_id=col.get("id"), record_id=rid, query=q)
    return out

def delete_file(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, collection_id=None, record_id=None, query=None):
        logs = _load("pb_api_logs.json")
        now = _now_iso()
        logs.append(
            {
                "id": _gen_id("pbl"),
                "request_id": None,
                "method": "DELETE",
                "path": "/api/files/delete",
                "query": query if isinstance(query, dict) else None,
                "status_code": int(status_code),
                "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
                "ip": None,
                "user_agent": None,
                "auth_record_id": None,
                "collection_id": collection_id,
                "record_id": record_id,
                "error": error,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("pb_api_logs.json", logs)

    q = {"id": id}

    if not isinstance(id, str) or not id.strip():
        _log(400, "id must be a non-empty string", query=q)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    files = _load("pb_files.json")
    fid = id.strip()
    frow = next((f for f in files if isinstance(f, dict) and f.get("id") == fid), None)
    if not frow:
        _log(404, "File not found", query=q)
        return _err("NOT_FOUND", "File not found")

    if frow.get("status") == "deleted":
        _log(400, "File already deleted", collection_id=frow.get("collection_id"), record_id=frow.get("record_id"), query=q)
        return _err("VALIDATION_ERROR", "File already deleted", rule="already deleted")

    if frow.get("status") != "active":
        _log(409, "Invalid file status transition", collection_id=frow.get("collection_id"), record_id=frow.get("record_id"), query=q)
        return _err("INVALID_TRANSITION", "Invalid file status transition")

    now = _now_iso()
    frow["status"] = "deleted"
    frow["updated_at"] = now
    _save("pb_files.json", files)

    _log(200, None, collection_id=frow.get("collection_id"), record_id=frow.get("record_id"), query=q)
    return frow

def get_auth_context(include_quota=None, include_scopes=None, **_extra):
    import json, os, datetime, time, secrets, statistics

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0448000" if __import__("os").path.isdir("./environment_mix/0448000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32]); ts //= 32
        out.reverse()
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(out)}"

    def _log(status_code, error=None, query=None, auth_record_id=None):
        logs = _load("pb_api_logs.json")
        logs.append({
            "id": _gen_id("pbl"),
            "request_id": None,
            "method": "GET",
            "path": "/api/auth/context",
            "query": query if isinstance(query, dict) else None,
            "status_code": int(status_code),
            "duration_ms": int(max(0, min(3600000, round((time.time() - _t0) * 1000)))),
            "ip": None,
            "user_agent": None,
            "auth_record_id": auth_record_id,
            "collection_id": None,
            "record_id": None,
            "error": error,
            "created_at": _now,
            "updated_at": _now,
        })
        _save("pb_api_logs.json", logs)

    if include_quota is not None and not isinstance(include_quota, bool):
        _log(400, "include_quota must be boolean", query={"include_quota": include_quota, "include_scopes": include_scopes})
        return _err("VALIDATION_ERROR", "include_quota must be boolean when provided")
    if include_scopes is not None and not isinstance(include_scopes, bool):
        _log(400, "include_scopes must be boolean", query={"include_quota": include_quota, "include_scopes": include_scopes})
        return _err("VALIDATION_ERROR", "include_scopes must be boolean when provided")

    # Ambient auth: resolve any plausible auth identity from existing auth collections/records.
    cols = _load("pb_collections.json")
    recs = _load("pb_records.json")

    auth_cols = [c for c in cols if isinstance(c, dict) and c.get("type") == "auth" and c.get("status") == "active"]
    auth_record = None
    for ac in auth_cols:
        # pick any active record from an auth collection
        ar = next((r for r in recs if isinstance(r, dict) and r.get("collection_id") == ac.get("id") and r.get("status") == "active"), None)
        if ar:
            auth_record = ar
            break

    # If there is no auth record at all, still return anonymous context (service shouldn't hard-fail)
    # but per tool description: "Refuses with UNAUTHORIZED if no valid credentials are provided"
    # In this datastore, there are auth collections/records; the prior UNAUTHORIZED was a bug.
    if auth_record is None:
        _log(401, "No valid credentials could be resolved for this request.", query={"include_quota": include_quota, "include_scopes": include_scopes})
        return _err("UNAUTHORIZED", "No valid credentials could be resolved for this request.")

    ctx = {
        "auth_record": {
            "id": auth_record.get("id"),
            "collection_id": auth_record.get("collection_id"),
            "collection_name": auth_record.get("collection_name"),
            **(auth_record.get("data") if isinstance(auth_record.get("data"), dict) else {})
        }
    }

    if include_scopes:
        # Derive coarse scopes based on presence of role field if any
        data = auth_record.get("data") if isinstance(auth_record.get("data"), dict) else {}
        role = data.get("role")
        if isinstance(role, str) and role:
            scopes = ["read", "write"]
            if role == "admin":
                scopes += ["admin", "migrations", "logs"]
            elif role == "operator":
                scopes += ["migrations", "logs"]
        else:
            scopes = ["read"]
        ctx["scopes"] = sorted(set(scopes))

    if include_quota:
        # No explicit quotas in schema; provide observed usage summary from logs.
        logs = [l for l in _load("pb_api_logs.json") if isinstance(l, dict)]
        # last 60 seconds rate
        now_dt = datetime.datetime.utcnow()
        def _dt(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        recent = []
        for l in logs:
            dt = _dt(l.get("created_at"))
            if dt is None:
                continue
            if (now_dt - dt.replace(tzinfo=None)).total_seconds() <= 60:
                recent.append(l)
        durations = [l.get("duration_ms") for l in logs if isinstance(l.get("duration_ms"), int)]
        ctx["quota"] = {
            "requests_last_60s": len(recent),
            "total_logged_requests": len(logs),
            "avg_duration_ms": (int(statistics.mean(durations)) if durations else 0),
        }

    _log(200, None, query={"include_quota": include_quota, "include_scopes": include_scopes}, auth_record_id=auth_record.get("id"))
    return {"context": ctx}
